/**
 * 宿主目录扫描：从给定根目录向下（最多 2 层）识别代码项目，用于新建工作空间
 * 向导第二步「自动识别项目」。识别依据：package.json（vue / react / 前端）、
 * pom.xml / gradle（Java）、requirements.txt / pyproject.toml / setup.py（Python）、
 * go.mod（Go）、≥3 个源码文件（通用代码项目）。
 * @module dsh-workspace-combiner/host/projectDetector
 */

import { readdir, readFile } from 'node:fs/promises'
import type { Dirent } from 'node:fs'
import { basename, join, relative } from 'node:path'
import type { DetectedProject, DirectoryCommands, MonorepoInfo, MonorepoKind, ProjectType } from '../core/types.ts'
import { isIgnored, loadGitignore, warnIoFailure } from './fileIndex.ts'

/** 最大扫描深度（根 = 0，向下到第 2 层子目录）。 */
const MAX_SCAN_DEPTH = 2

/** 最多访问目录数（防失控）。 */
const MAX_VISITED_DIRS = 256

/** 视为「代码文件」的扩展名（命中 ≥3 个即判为通用代码项目）。 */
const CODE_EXTENSIONS = new Set([
  '.java', '.js', '.jsx', '.ts', '.tsx', '.vue', '.py', '.go', '.rs',
  '.c', '.cc', '.cpp', '.h', '.hpp', '.cs', '.rb', '.php', '.kt', '.scala', '.swift',
])

interface PackageInfo {
  deps: string[]
  scripts: Set<string>
  packageManager?: string
  workspaces: string[]
}

/** 读 package.json 的依赖、脚本与包管理器声明（失败返回空）。 */
async function readPackageInfo(dir: string): Promise<PackageInfo> {
  try {
    const raw = await readFile(join(dir, 'package.json'), 'utf8')
    const pkg = JSON.parse(raw) as {
      dependencies?: Record<string, unknown>
      devDependencies?: Record<string, unknown>
      scripts?: Record<string, unknown>
      packageManager?: unknown
      workspaces?: unknown
    }
    const workspaceValue = pkg.workspaces
    const workspaces = Array.isArray(workspaceValue)
      ? workspaceValue.filter((value): value is string => typeof value === 'string')
      : workspaceValue !== null && typeof workspaceValue === 'object' && Array.isArray((workspaceValue as { packages?: unknown }).packages)
        ? (workspaceValue as { packages: unknown[] }).packages.filter((value): value is string => typeof value === 'string')
        : []
    return {
      deps: Object.keys({ ...pkg.dependencies, ...pkg.devDependencies }),
      scripts: new Set(Object.entries(pkg.scripts ?? {}).filter(([, value]) => typeof value === 'string' && value.trim() !== '').map(([name]) => name)),
      ...(typeof pkg.packageManager === 'string' ? { packageManager: pkg.packageManager } : {}),
      workspaces,
    }
  } catch (error) {
    // 缺失（ENOENT）是常态；权限/JSON 损坏要能看见，否则会表现成"未识别到项目"。
    warnIoFailure('package-json', join(dir, 'package.json'), error)
    return { deps: [], scripts: new Set(), workspaces: [] }
  }
}

function normalizeRelative(path: string): string {
  return path.split('\\').join('/').replace(/^\.\//, '').replace(/\/$/, '')
}

function globPattern(pattern: string): RegExp {
  const normalized = normalizeRelative(pattern)
  let source = ''
  for (let index = 0; index < normalized.length; index++) {
    const char = normalized[index]
    if (char === '*' && normalized[index + 1] === '*') {
      source += '.*'
      index++
    } else if (char === '*') source += '[^/]*'
    else source += char.replace(/[|\\{}()[\]^$+?.]/g, '\\$&')
  }
  return new RegExp('^' + source + '$')
}

async function readText(path: string): Promise<string | undefined> {
  try { return await readFile(path, 'utf8') } catch (error) { warnIoFailure('project-scan', path, error); return undefined }
}

async function childDirectories(root: string, maxDepth = 4): Promise<string[]> {
  const output: string[] = []
  // 与文件索引共用同一套忽略规则：否则 dist/ build/ target/ 里的源码会被当成包。
  const patterns = await loadGitignore(root)
  const walk = async (dir: string, depth: number): Promise<void> => {
    if (depth > maxDepth || output.length >= MAX_VISITED_DIRS) return
    let entries: Dirent[]
    try { entries = await readdir(dir, { withFileTypes: true }) } catch (error) { warnIoFailure('monorepo-scan', dir, error); return }
    for (const entry of entries) {
      if (!entry.isDirectory() || entry.name.startsWith('.')) continue
      const child = join(dir, entry.name)
      if (isIgnored(normalizeRelative(relative(root, child)), true, patterns)) continue
      output.push(child)
      await walk(child, depth + 1)
    }
  }
  await walk(root, 1)
  return output
}

function yamlWorkspacePatterns(text: string): string[] {
  const lines = text.split(/\r?\n/)
  const patterns: string[] = []
  let inPackages = false
  for (const line of lines) {
    if (/^packages\s*:/.test(line.trim())) { inPackages = true; continue }
    if (!inPackages) continue
    const match = line.match(/^\s*-\s*['"]?([^'"#]+?)['"]?\s*(?:#.*)?$/)
    if (match !== null) patterns.push(match[1].trim())
    else if (line.trim() !== '' && !/^\s/.test(line)) break
  }
  return patterns
}

function mavenModules(text: string): string[] {
  const modules = text.match(/<modules>[\s\S]*?<\/modules>/i)?.[0] ?? ''
  return [...modules.matchAll(/<module>\s*([^<]+?)\s*<\/module>/gi)].map(match => match[1].trim())
}

function gradleModules(text: string): string[] {
  const modules: string[] = []
  for (const line of text.split(/\r?\n/)) {
    if (!/^\s*include\b/.test(line)) continue
    for (const match of line.matchAll(/['"]:?(.*?)['"]/g)) modules.push(match[1].replaceAll(':', '/'))
  }
  return modules
}

async function detectMonorepo(root: string, entries: readonly string[]): Promise<MonorepoInfo | undefined> {
  const names = new Set(entries)
  const packageInfo = names.has('package.json') ? await readPackageInfo(root) : undefined
  let kind: MonorepoKind | undefined
  let patterns: string[] = packageInfo?.workspaces ?? []

  if (names.has('pnpm-workspace.yaml')) {
    kind = 'pnpm'
    patterns = yamlWorkspacePatterns((await readText(join(root, 'pnpm-workspace.yaml'))) ?? '')
  } else if (names.has('nx.json')) kind = 'nx'
  else if (names.has('turbo.json')) kind = 'turbo'
  else if (names.has('lerna.json')) {
    kind = 'lerna'
    try {
      const lerna = JSON.parse((await readText(join(root, 'lerna.json'))) ?? '{}') as { packages?: unknown }
      if (patterns.length === 0 && Array.isArray(lerna.packages)) patterns = lerna.packages.filter((value): value is string => typeof value === 'string')
    } catch { /* malformed manifests are ignored */ }
  } else if (patterns.length > 0) {
    const manager = packageManager(entries, packageInfo?.packageManager)
    kind = manager
  } else if (names.has('pom.xml')) {
    patterns = mavenModules((await readText(join(root, 'pom.xml'))) ?? '')
    if (patterns.length > 0) kind = 'maven'
  } else if (names.has('settings.gradle') || names.has('settings.gradle.kts')) {
    const file = names.has('settings.gradle.kts') ? 'settings.gradle.kts' : 'settings.gradle'
    patterns = gradleModules((await readText(join(root, file))) ?? '')
    if (patterns.length > 0) kind = 'gradle'
  }

  if (kind === undefined) return undefined
  if (patterns.length === 0 && (kind === 'nx' || kind === 'turbo')) patterns = ['apps/*', 'packages/*', 'libs/*']
  const positive = patterns.filter(pattern => !pattern.startsWith('!')).map(globPattern)
  const negative = patterns.filter(pattern => pattern.startsWith('!')).map(pattern => globPattern(pattern.slice(1)))
  const dirs = await childDirectories(root)
  const packageDirs = dirs.filter(dir => {
    const path = normalizeRelative(relative(root, dir))
    return positive.some(pattern => pattern.test(path)) && !negative.some(pattern => pattern.test(path))
  })
  const packages = []
  for (const dir of packageDirs) {
    let childEntries: Dirent[]
    try { childEntries = await readdir(dir, { withFileTypes: true }) } catch (error) { warnIoFailure('monorepo-scan', dir, error); continue }
    const childNames = childEntries.map(entry => entry.name)
    const projectType = await detectType(dir, childNames)
    if (projectType === 'none') continue
    packages.push({ name: basename(dir), path: normalizeRelative(relative(root, dir)), projectType })
  }
  packages.sort((a, b) => a.path.localeCompare(b.path))
  return { kind, packages }
}

/** 依据目录项识别项目类型（none 表示不是项目根）。 */
async function detectType(dir: string, entries: string[]): Promise<ProjectType> {
  const names = new Set(entries)
  if (names.has('pom.xml') || names.has('build.gradle') || names.has('build.gradle.kts') || names.has('settings.gradle')) return 'java'
  if (names.has('go.mod')) return 'go'
  if (names.has('requirements.txt') || names.has('pyproject.toml') || names.has('setup.py')) return 'python'
  if (names.has('package.json')) {
    const { deps } = await readPackageInfo(dir)
    // next 基于 react、webpack 常作为 vue/react 的构建依赖，按「更具体优先」判定。
    if (deps.includes('next')) return 'frontend-next'
    if (deps.includes('vue')) return 'frontend-vue'
    if (deps.includes('react') || deps.includes('react-dom')) return 'frontend-react'
    if (deps.includes('webpack')) return 'frontend-webpack'
    return 'frontend'
  }
  const codeCount = entries.filter(e => {
    const dot = e.lastIndexOf('.')
    return dot > 0 && CODE_EXTENSIONS.has(e.slice(dot).toLowerCase())
  }).length
  return codeCount >= 3 ? 'generic' : 'none'
}

/** 项目识别依据描述（hover 提示用）。 */
function evidenceFor(type: ProjectType): string {
  switch (type) {
    case 'java': return 'pom.xml / build.gradle'
    case 'go': return 'go.mod'
    case 'python': return 'requirements.txt / pyproject.toml'
    case 'frontend-vue': return 'package.json + vue'
    case 'frontend-react': return 'package.json + react'
    case 'frontend-webpack': return 'package.json + webpack'
    case 'frontend-next': return 'package.json + next'
    case 'frontend': return 'package.json'
    case 'generic': return '源码文件'
    case 'none': return ''
  }
}

/**
 * 按项目类型给出常用命令默认值（面板预填，用户可改）。
 * 只给「几乎必然正确」的通用命令：需要额外参数（profile、模块名）的一律留空，
 * 宁可让用户自己填，也不要注入一条跑不通的命令。
 * @param type - 识别出的项目类型。
 * @returns 默认命令（无把握时缺字段）。
 */
export function defaultCommands(type: ProjectType): DirectoryCommands | undefined {
  switch (type) {
    case 'java': return { run: 'mvn spring-boot:run', test: 'mvn test', build: 'mvn -q package -DskipTests' }
    case 'go': return { run: 'go run .', test: 'go test ./...', build: 'go build ./...' }
    case 'python': return { test: 'pytest' }
    case 'frontend-next': return { run: 'pnpm dev', test: 'pnpm test', build: 'pnpm build' }
    case 'frontend-vue':
    case 'frontend-react':
    case 'frontend-webpack':
    case 'frontend': return { run: 'pnpm dev', test: 'pnpm test', build: 'pnpm build' }
    default: return undefined
  }
}

export function suggestedGroup(type: ProjectType, name: string): 'backend' | 'frontend' | 'reference' | 'other' {
  if (type.startsWith('frontend')) return 'frontend'
  if (type === 'java' || type === 'go' || type === 'python') return 'backend'
  if (/\b(shared|common|sdk|types?|contracts?|schemas?|proto)\b/i.test(name.replace(/[-_.]+/g, ' '))) return 'reference'
  return 'other'
}

function packageManager(entries: readonly string[], declared?: string): 'pnpm' | 'npm' | 'yarn' | 'bun' {
  const name = declared?.split('@')[0]
  if (name === 'pnpm' || name === 'npm' || name === 'yarn' || name === 'bun') return name
  if (entries.includes('pnpm-lock.yaml')) return 'pnpm'
  if (entries.includes('yarn.lock')) return 'yarn'
  if (entries.includes('bun.lock') || entries.includes('bun.lockb')) return 'bun'
  return 'npm'
}

function scriptCommand(manager: 'pnpm' | 'npm' | 'yarn' | 'bun', script: string): string {
  if (manager === 'npm') return 'npm run ' + script
  if (manager === 'bun') return 'bun run ' + script
  return manager + ' ' + script
}

async function detectedCommands(dir: string, type: ProjectType, entries: readonly string[]): Promise<DirectoryCommands | undefined> {
  if (type.startsWith('frontend')) {
    const info = await readPackageInfo(dir)
    const manager = packageManager(entries, info.packageManager)
    const runScript = info.scripts.has('dev') ? 'dev' : info.scripts.has('start') ? 'start' : undefined
    const commands: DirectoryCommands = {
      ...(runScript === undefined ? {} : { run: scriptCommand(manager, runScript) }),
      ...(info.scripts.has('test') ? { test: scriptCommand(manager, 'test') } : {}),
      ...(info.scripts.has('build') ? { build: scriptCommand(manager, 'build') } : {}),
    }
    return Object.keys(commands).length === 0 ? undefined : commands
  }
  if (type === 'java') {
    if (entries.includes('pom.xml')) {
      const runner = entries.includes('mvnw') ? './mvnw' : 'mvn'
      return { run: runner + ' spring-boot:run', test: runner + ' test', build: runner + ' package -DskipTests' }
    }
    const runner = entries.includes('gradlew') ? './gradlew' : 'gradle'
    return { run: runner + ' bootRun', test: runner + ' test', build: runner + ' build -x test' }
  }
  return defaultCommands(type)
}

/**
 * 从根目录向下扫描（最多 2 层），返回识别到的项目列表。
 *
 * 命中项目后**继续下钻**：父目录本身像项目（≥3 个源码文件）时，旧实现会直接
 * return，把真正的子项目整片漏掉。唯一的例外是 Monorepo 已声明并收进
 * `monorepo.packages` 的包目录——它们不再是独立工作区根，避免重复上报。
 */
export async function scanDirectory(root: string): Promise<DetectedProject[]> {
  const found: DetectedProject[] = []
  let visited = 0

  const walk = async (dir: string, depth: number, monorepo: { root: string; packages: ReadonlySet<string> } | undefined): Promise<void> => {
    if (depth > MAX_SCAN_DEPTH || visited >= MAX_VISITED_DIRS) return
    visited++
    let entries: Dirent[]
    try {
      entries = await readdir(dir, { withFileTypes: true })
    } catch (error) {
      warnIoFailure('project-scan', dir, error)
      return
    }
    const names = entries.map(e => e.name)
    const type = await detectType(dir, names)
    const detected = await detectMonorepo(dir, names)
    if (type !== 'none' || detected !== undefined) {
      const name = basename(dir)
      const resolvedType = type === 'none' ? 'generic' : type
      const commands = await detectedCommands(dir, resolvedType, names)
      found.push({
        root: dir,
        name,
        type: resolvedType,
        evidence: detected === undefined ? evidenceFor(resolvedType) : `${detected.kind} monorepo · ${detected.packages.length} packages`,
        suggestedGroup: suggestedGroup(resolvedType, name),
        ...(commands === undefined ? {} : { commands }),
        ...(detected === undefined ? {} : { monorepo: detected }),
      })
    }
    if (depth >= MAX_SCAN_DEPTH) return
    // 本目录新发现了 Monorepo：以它为基准判断后续子目录是否为已声明的包。
    const context = detected === undefined ? monorepo : { root: dir, packages: new Set(detected.packages.map(pkg => pkg.path)) }
    const patterns = await loadGitignore(dir)
    for (const entry of entries) {
      if (!entry.isDirectory() || entry.name.startsWith('.')) continue
      // 与文件索引共用忽略规则：dist/ build/ target/ .venv 等不再被当成项目。
      if (isIgnored(entry.name, true, patterns)) continue
      const child = join(dir, entry.name)
      if (context !== undefined && context.packages.has(normalizeRelative(relative(context.root, child)))) continue
      await walk(child, depth + 1, context)
    }
  }

  await walk(root, 0, undefined)
  return found
}
